  @by_name for language <- @languages,
               name <- [language.id | language.aliases],
               into: %{},
               do: {String.downcase(name), language}

  def all, do: @languages

  def fetch(name) when is_binary(name) do
    Map.fetch(@by_name, String.downcase(name))
  end
end
